script:
(function () {
  'use strict';
  // HSA projection, annual steps. At the start of each year your contribution and the employer's
  // go in (together capped at the limit for your coverage and age), that year's medical expenses
  // are paid out (never more than the balance), and the rest grows at the expected return:
  //   balance = (balance + contributions - expenses paid) x (1 + r)
  // Tax saved = your contribution x (federal + state rate, + 7.65% FICA if made through payroll).
  // CHECKS (Node, scratch tests): no expenses, $3,900 a year (you $3,400 + employer $500) at 5%
  // for 30 years from $0 = 3,900 x 1.05 x (1.05^30 - 1) / 0.05 = $272,061.40, plus $2,000 x
  // 1.05^30 = $8,643.88; 0% return -> balance = sum of contributions - expenses; self-only cap
  // $4,400 and $5,400 from age 55; family $8,750 / $9,750; employer $500 + max -> you $3,900;
  // tax saved on $3,400 at 22% + 5% + 7.65% = $1,178.10 a year; expenses above the balance are
  // reported as paid out of pocket.
  // ---- 2026 HSA LIMITS (calendar year 2026) ---------------------------------------------------
  // Source: IRS Rev. Proc. 2025-19 (IRC 223 inflation adjustments for 2026). Catch-up: IRC
  // 223(b)(3)(B), a fixed $1,000 for account holders 55 or older (not indexed; IRS Pub. 969).
  // FICA: 6.2% Social Security + 1.45% Medicare employee rates (IRC 3101).
  var HSA = {
    year: 2026,
    limit: { self: 4400, family: 8750 },
    catchUp55: 1000,
    hdhpMinDeductible: { self: 1700, family: 3400 },
    hdhpOutOfPocketMax: { self: 8500, family: 17000 }
  };
  var FICA_RATE = 0.0765;
  // --------------------------------------------------------------------------------------------

  function limitFor(coverage, age) { return HSA.limit[coverage] + (age >= 55 ? HSA.catchUp55 : 0); }

  // p: coverage, age, balance, years, contrib, employer, max, expenses, rate, costRise, taxRate,
  // stop65 (rates as decimals; taxRate already combined).
  function project(p) {
    var bal = p.balance, rows = [], totIn = 0, totYou = 0, paid = 0, short = 0, capped = false;
    for (var y = 0; y < p.years; y++) {
      var age = p.age + y, lim = limitFor(p.coverage, age);
      var eligible = !(p.stop65 && age >= 65);
      var er = eligible ? Math.min(p.employer, lim) : 0;
      var room = Math.max(0, lim - er);
      var you = eligible ? (p.max ? room : Math.min(p.contrib, room)) : 0;
      if (eligible && !p.max && p.contrib > room + 0.005) capped = true;
      if (eligible && p.employer > lim + 0.005) capped = true;
      bal += you + er;
      var expense = p.expenses * Math.pow(1 + p.costRise, y);
      var pay = Math.min(expense, bal);
      short += expense - pay;
      bal -= pay;
      var growth = bal * p.rate;
      bal += growth;
      totIn += you + er; totYou += you; paid += pay;
      rows.push({ age: age, inflow: you + er, paid: pay, growth: growth, balance: bal });
    }
    return { balance: bal, totIn: totIn, totYou: totYou, paid: paid, short: short, capped: capped, rows: rows,
             growth: bal - p.balance - totIn + paid, taxSaved: totYou * p.taxRate };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); } };

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function update() {
    var coverage = document.getElementById('hsCoverage').value;
    var age = Math.round(num('hsAge')), balance = num('hsBalance'), years = Math.round(num('hsYears')),
        contrib = num('hsContrib'), employer = num('hsEmployer'), expenses = num('hsExpenses'), rate = num('hsRate'),
        fed = num('hsFed'), state = num('hsState'), costRise = num('hsCostRise');
    var payroll = document.getElementById('hsPayroll').checked, stop65 = document.getElementById('hsStop65').checked,
        max = document.getElementById('hsMax').checked;
    var error = document.getElementById('hsError');
    var bad = [age, balance, years, contrib, employer, expenses, rate, fed, state, costRise].some(isNaN) ||
              age < 18 || age > 99 || years < 1 || years > 60 || balance < 0 || contrib < 0 || employer < 0 ||
              expenses < 0 || rate < 0 || rate > 30 || fed < 0 || fed > 37 || state < 0 || state > 15 ||
              costRise < 0 || costRise > 20;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter an age from 18 to 99, 1 to 60 years, non-negative amounts, a return up to 30%, ' +
                          'a federal rate up to 37%, a state rate up to 15% and a cost increase up to 20%.';
      return;
    }
    var taxRate = fed / 100 + state / 100 + (payroll ? FICA_RATE : 0);
    var r = project({ coverage: coverage, age: age, balance: balance, years: years, contrib: contrib, employer: employer,
                      max: max, expenses: expenses, rate: rate / 100, costRise: costRise / 100, taxRate: taxRate, stop65: stop65 });
    set('hsFutureLabel', 'HSA balance at age ' + (age + years));
    set('hsFuture', money.format(r.balance));
    set('hsContribTotal', money.format(r.totIn));
    set('hsPaid', money.format(r.paid));
    set('hsGrowth', money.format(r.growth));
    set('hsTaxSaved', money.format(r.taxSaved));
    var lim0 = limitFor(coverage, age);
    var first = r.rows[0];
    set('hsFirstYear', (stop65 && age >= 65) ? 'At 65 or older with Medicare you can no longer contribute, but you can keep spending and investing the balance.' :
        HSA.year + ' limit for your coverage and age: ' + money.format(lim0) + '. First year: you put in ' +
        money.format(first.inflow - Math.min(employer, lim0)) + ', your employer ' + money.format(Math.min(employer, lim0)) +
        ', saving you about ' + money.format((first.inflow - Math.min(employer, lim0)) * taxRate) + ' in tax.');
    var capEl = document.getElementById('hsCapped');
    capEl.hidden = !r.capped;
    if (r.capped) set('hsCapped', 'Your contributions plus your employer\'s are above the ' + HSA.year +
        ' limit in some years, so the projection reduces them to the limit. Excess contributions owe a 6% excise tax each year until removed.');
    var shortEl = document.getElementById('hsShort');
    shortEl.hidden = !(r.short > 0.5);
    if (r.short > 0.5) set('hsShort', 'In some years your expenses are larger than the HSA balance. About ' + money.format(r.short) +
        ' in total would have to be paid from other money.');
    var body = document.getElementById('hsSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.age, money.format(row.inflow), money.format(row.paid), money.format(row.growth), money.format(row.balance)]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    set('hsLimSelf', money.format(HSA.limit.self));
    set('hsLimFamily', money.format(HSA.limit.family));
    set('hsLimCatch', money.format(HSA.catchUp55));
    set('hsLimDed', money.format(HSA.hdhpMinDeductible.self) + ' / ' + money.format(HSA.hdhpMinDeductible.family));
    set('hsLimOop', money.format(HSA.hdhpOutOfPocketMax.self) + ' / ' + money.format(HSA.hdhpOutOfPocketMax.family));
    var form = document.getElementById('hsForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
